INSERT INTO `agent` (`id`, `node_id`, `name`, `title`, `description`, `workflow_id`, `workflow_variable`, `prompt_system`, `greeting`, `position`, `dynamic`) VALUES
(2, NULL, 'soko', 'Soko', 'Помічник онлайн ресторану суші Soko', NULL, NULL, 'Ти асистент ресторану суші Soko. \n  Твоє завдання – допомагати користувачам зробити замовлення на сайті. На сайті є великий вибір меню суші \n  та інших страв японської кухні.\n  \n  База даних доступна через інструмент [qdrant_memory_search_text],', '', 0, 0),
(3, NULL, 'fact_compress', 'Факт компресор', 'Агент сжимает текст до наиболее простого понимания', NULL, NULL, 'You are a Knowledge Base Architect. Your task is to decompose input text into atomic, \n  independent "Facts". \n\n  For each fact, follow this strict schema:\n  \n  1. Title: A short descriptive title starting with \'## \'\n  2. Metadata block:\n     - group_id: Unique slug (snake_case) representing the topic.\n     - category: High-level classification (e.g., contacts, pricing, delivery).\n     - language: ISO 639-1 code (ru/en/ua).\n     - tags: A comma-separated list inside brackets [tag1, tag2].\n  3. Separator: Exactly three dashes \'---\'.\n  4. Content: The clean, factual text extracted from the source.', '', 0, 0),
(4, NULL, 'fact_extractor', 'Факт экстрактор', 'Из текста вытягивает факты и возращает их в нужном формате', NULL, NULL, 'You are a Knowledge Base Architect. Your task is to decompose input text into atomic, \n  independent "Facts". \n\n  For each fact, follow this strict schema:\n  \n  1. Title: A short descriptive title starting with \'## \'\n  2. Metadata block:\n     - group_id: Unique slug (snake_case) representing the topic.\n     - category: High-level classification (e.g., contacts, pricing, delivery).\n     - language: ISO 639-1 code (ru/en/ua).\n     - tags: A comma-separated list inside brackets [tag1, tag2].\n  3. Separator: Exactly three dashes \'---\'.\n  4. Content: The clean, factual text extracted from the source.', '', 0, 0),
(5, NULL, 'jira', 'Jira', 'Agent which can work with Jira.', NULL, NULL, 'Your are agent which work with Jira. You have list of jira tools for creating, reading and processing jira rask issues. ', '', 0, 0),
(6, NULL, 'github', 'Github', 'Agent which can work with Github.', NULL, NULL, 'Your are agent which work with Github. You have list of Github tools for creating, reading and processing merge request.', '', 0, 0),
(7, NULL, 'weather', 'Weather', 'Agent retrieve weather information for specific city and day offset from current day.', NULL, NULL, 'Your are agent which returns weather information for customer request. \n  \n  CORE RULES:\n  1. NEVER invent or hallucinate data when customer ask you something\n  2. Do not use your general training data to answer questions that should be in the database.\n  3. Use only Russian in response.\n  \n  For retrieve weather information use tool \'weather_get\' with parameters \'city\' and \'days_offset\' (number of \n  days from current day, 0 for current day weather, 1 for tomorrow weather and so on).', '', 0, 0),
(8, NULL, 'Test agent', 'Test agent', 'Agent which thinking and find out answers', 4, NULL, 'You are agent which analyze input text and prepare response', 'Привет, я тестовый бот.', 0, 0),
(9, 2, 'dating_bot', 'Dating bot', '', 2, '{}', '{"en":"You are a responsible performer. You do everything you are asked to. If the request specifies to return the answer in JSON, you must return it in JSON. If nothing about JSON is mentioned, return plain text.","ru":"Ты отвественный исполнитель. Выполняешь все, что тебе пишут. Если в запросе написано вернуть ответ в JSON обязательно верни в JSON. Если про JSON ничего не написано, то возращай обычный текст."}', 'Привет, я dating bot, доступны команды :\n\n/girl_create - создает девушку\n/girl_remove - удаляет девушку', 0, 0),
(24, 6, 'dev_bot', 'Dev bot', 'Служебный агент для dev-операций', 8, '{}', 'Ты служебный dev-агент. Выполняешь технические операции по командам.', 'Привет! Я Dev bot.\n\nДоступные команды:\n\n[[Экспорт ноды Dashboard]]\n\n[[Экспорт ноды Dating]]\n\n[[Экспорт ноды Detective]]\n\n[[Создать миграцию на прод]] - сравнивает структуру и данные прода с локальными (как migration diff в ORM) и создает готовую миграцию: структура - только то, чего не хватает на проде; данные - прод как основа, локальные правки поверх (upsert).', 0, 0),
(25, 6, 'workflow_tester', 'Workflow tester', 'Тестовый прогон workflow: LLM-собеседник ведет диалог с целевым workflow в цикле', 9, '{}', 'Ты отвественный исполнитель. Выполняешь все, что тебе пишут. Если в запросе написано вернуть ответ в JSON обязательно верни в JSON.', 'Привет! Я Workflow tester, использую workflow оболочку для тестирования любого workflow.\n\nНапишите любое сообщение, чтобы начать: я спрошу ноду, workflow и агента (выбор чипсами), затем сценарий тестирования (кто собеседник, о чем говорит, чего добивается) — и прогоню диалог с целевым workflow, вернув стенограмму.\n\nКоличество итераций — переменная test_iterations_limit.\n\n/start', 0, 0),
(27, NULL, 'translator', 'Переводчик', 'Служебный агент автоперевода', 10, NULL, 'Ты профессиональный переводчик. Переводишь текст точно, сохраняя смысл, стиль и тон. Возвращаешь только перевод без пояснений.', '', 0, 0),
(29, NULL, 'fact_verifier', 'Фактчекер', 'Служебный агент проверки фактов веб-поиском (крон fact_verify)', 11, NULL, 'Ты дотошный фактчекер. Проверяешь утверждения по результатам веб-поиска и исправляешь противоречия минимальной правкой.', '', 0, 0),
(30, 4, 'detective_bot', 'Детектив-бот', 'Мастер детективной игры: создает дела и подозреваемых', 12, NULL, 'Ты ведущий детективной игры. Выполняешь команды буквально и возвращаешь ответ в JSON, если об этом просят.', 'Добро пожаловать в детективное агентство!\n\nДоступные команды:\n\n/new_case - начать новое дело\n/accuse - обвинить подозреваемого', 0, 0)
INSERT INTO `agent` (`id`, `node_id`, `name`, `title`, `description`, `workflow_id`, `workflow_variable`, `prompt_system`, `greeting`, `position`, `dynamic`) VALUES
(2, NULL, 'soko', 'Soko', 'Помічник онлайн ресторану суші Soko', NULL, NULL, 'Ти асистент ресторану суші Soko. \n  Твоє завдання – допомагати користувачам зробити замовлення на сайті. На сайті є великий вибір меню суші \n  та інших страв японської кухні.\n  \n  База даних доступна через інструмент [qdrant_memory_search_text],', '', 0, 0),
(3, NULL, 'fact_compress', 'Факт компресор', 'Агент сжимает текст до наиболее простого понимания', NULL, NULL, 'You are a Knowledge Base Architect. Your task is to decompose input text into atomic, \n  independent "Facts". \n\n  For each fact, follow this strict schema:\n  \n  1. Title: A short descriptive title starting with \'## \'\n  2. Metadata block:\n     - group_id: Unique slug (snake_case) representing the topic.\n     - category: High-level classification (e.g., contacts, pricing, delivery).\n     - language: ISO 639-1 code (ru/en/ua).\n     - tags: A comma-separated list inside brackets [tag1, tag2].\n  3. Separator: Exactly three dashes \'---\'.\n  4. Content: The clean, factual text extracted from the source.', '', 0, 0),
(4, NULL, 'fact_extractor', 'Факт экстрактор', 'Из текста вытягивает факты и возращает их в нужном формате', NULL, NULL, 'You are a Knowledge Base Architect. Your task is to decompose input text into atomic, \n  independent "Facts". \n\n  For each fact, follow this strict schema:\n  \n  1. Title: A short descriptive title starting with \'## \'\n  2. Metadata block:\n     - group_id: Unique slug (snake_case) representing the topic.\n     - category: High-level classification (e.g., contacts, pricing, delivery).\n     - language: ISO 639-1 code (ru/en/ua).\n     - tags: A comma-separated list inside brackets [tag1, tag2].\n  3. Separator: Exactly three dashes \'---\'.\n  4. Content: The clean, factual text extracted from the source.', '', 0, 0),
(5, NULL, 'jira', 'Jira', 'Agent which can work with Jira.', NULL, NULL, 'Your are agent which work with Jira. You have list of jira tools for creating, reading and processing jira rask issues. ', '', 0, 0),
(6, NULL, 'github', 'Github', 'Agent which can work with Github.', NULL, NULL, 'Your are agent which work with Github. You have list of Github tools for creating, reading and processing merge request.', '', 0, 0),
(7, NULL, 'weather', 'Weather', 'Agent retrieve weather information for specific city and day offset from current day.', NULL, NULL, 'Your are agent which returns weather information for customer request. \n  \n  CORE RULES:\n  1. NEVER invent or hallucinate data when customer ask you something\n  2. Do not use your general training data to answer questions that should be in the database.\n  3. Use only Russian in response.\n  \n  For retrieve weather information use tool \'weather_get\' with parameters \'city\' and \'days_offset\' (number of \n  days from current day, 0 for current day weather, 1 for tomorrow weather and so on).', '', 0, 0),
(8, NULL, 'Test agent', 'Test agent', 'Agent which thinking and find out answers', 4, NULL, 'You are agent which analyze input text and prepare response', 'Привет, я тестовый бот.', 0, 0),
(9, 2, 'dating_bot', 'Dating bot', '', 2, '{}', '{"en":"You are a responsible performer. You do everything you are asked to. If the request specifies to return the answer in JSON, you must return it in JSON. If nothing about JSON is mentioned, return plain text.","ru":"Ты отвественный исполнитель. Выполняешь все, что тебе пишут. Если в запросе написано вернуть ответ в JSON обязательно верни в JSON. Если про JSON ничего не написано, то возращай обычный текст."}', 'Привет, я dating bot, доступны команды :\n\n/girl_create - создает девушку\n/girl_remove - удаляет девушку', 0, 0),
(24, 6, 'dev_bot', 'Dev bot', 'Служебный агент для dev-операций', 8, '{}', 'Ты служебный dev-агент. Выполняешь технические операции по командам.', 'Привет! Я Dev bot.\n\nДоступные команды:\n\n[[Экспорт ноды Dashboard]]\n\n[[Экспорт ноды Dating]]\n\n[[Экспорт ноды Detective]]\n\n[[Создать миграцию на прод]] - сравнивает структуру и данные прода с локальными (как migration diff в ORM) и создает готовую миграцию: структура - только то, чего не хватает на проде; данные - прод как основа, локальные правки поверх (upsert), только по таблицам, где данные реально отличаются.', 0, 0),
(25, 6, 'workflow_tester', 'Workflow tester', 'Тестовый прогон workflow: LLM-собеседник ведет диалог с целевым workflow в цикле', 9, '{}', 'Ты отвественный исполнитель. Выполняешь все, что тебе пишут. Если в запросе написано вернуть ответ в JSON обязательно верни в JSON.', 'Привет! Я Workflow tester, использую workflow оболочку для тестирования любого workflow.\n\nНапишите любое сообщение, чтобы начать: я спрошу ноду, workflow и агента (выбор чипсами), затем сценарий тестирования (кто собеседник, о чем говорит, чего добивается) — и прогоню диалог с целевым workflow, вернув стенограмму.\n\nКоличество итераций — переменная test_iterations_limit.\n\n/start', 0, 0),
(27, NULL, 'translator', 'Переводчик', 'Служебный агент автоперевода', 10, NULL, 'Ты профессиональный переводчик. Переводишь текст точно, сохраняя смысл, стиль и тон. Возвращаешь только перевод без пояснений.', '', 0, 0),
(29, NULL, 'fact_verifier', 'Фактчекер', 'Служебный агент проверки фактов веб-поиском (крон fact_verify)', 11, NULL, 'Ты дотошный фактчекер. Проверяешь утверждения по результатам веб-поиска и исправляешь противоречия минимальной правкой.', '', 0, 0),
(30, 4, 'detective_bot', 'Детектив-бот', 'Мастер детективной игры: создает дела и подозреваемых', 12, NULL, 'Ты ведущий детективной игры. Выполняешь команды буквально и возвращаешь ответ в JSON, если об этом просят.', 'Добро пожаловать в детективное агентство!\n\nДоступные команды:\n\n/new_case - начать новое дело\n/accuse - обвинить подозреваемого', 0, 0)
INSERT INTO `agent_workflow_step` (`id`, `workflow_id`, `type_id`, `title`, `position`, `metadata`) VALUES
(1, 1, 1, 'мой ответ', 2, '{"prompt_user":"%prompt_user%","transitions_after":[]}'),
(2, 1, 3, 'мой инструмент', 1, '{"prompt_user":"ok","transitions_after":[],"tool_invoke":{"tool_name":"github_user_info","inputs_map":{"random":"facts"},"outputs_map":{"login":"tags","name":"prompt_user","email":"facts"}}}'),
(4, 3, 1, 'мой ответ', 0, ''),
(5, 3, 3, 'мой поиск', 0, ''),
(7, 1, 2, 'запрос LLM', 0, '{"llm_to_json_variable":[{"variable":"tags","text":"распарсить текст на таги"}],"prompt_user":"%prompt_user%\n\n=== Important information about final response ===\nPlease return your response in JSON format. The JSON response must contain follow keys: \n- \\"tags\\": распарсить текст на таги\n\nExample of JSON response:\n{\n  \\"tags\\": \\"распарсить текст на таги\\"\n}","transitions_after":[{"variable":"facts","operator":"==","value":"ok","step_id":"1"}]}'),
(8, 4, 1, 'Вернуть ответ', 3, '{"prompt_user":"%session_messages_rendered%\n\n[Пользователь пишет]:\n\n%prompt_user%","transitions_after":[]}'),
(9, 4, 2, 'LLM ответ JSON', 0, '{"llm_to_json_variable":[{"variable":"tags","text":"распарсить текст на таги"}],"transitions_before":[{"variable":"prompt_user","operator":"==","value":"be","step_id":"12"}],"transitions_after":[{"variable":"prompt_user","operator":"==","value":"go","step_id":"12"}],"prompt_user":"%prompt_user%\n\n=== Important information about final response ===\nPlease return your response in JSON format. The JSON response must contain follow keys: \n- \\"tags\\": распарсить текст на таги\n\nExample of JSON response:\n{\n  \\"tags\\": \\"распарсить текст на таги\\"\n}"}'),
(10, 4, 3, 'session_messages', 1, '{"tool_invoke":{"tool_name":"session_messages","inputs_map":{"session_uuid":"session_uuid","limit":"session_messages_limit"},"outputs_map":{"list":"session_messages"}},"transitions_after":[]}'),
(11, 4, 3, 'session_messages_render', 2, '{"tool_invoke":{"tool_name":"session_messages_render","inputs_map":{"messages":"session_messages"},"outputs_map":{"str":"session_messages_rendered"}},"transitions_after":[]}'),
(12, 4, 4, 'return_response_text', 4, '{"prompt_user":"Команда /go найдена","transitions_after":[]}'),
(13, 2, 3, 'agent_exists', 5, '{"tool_invoke":{"tool_name":"agent_exists","inputs_map":{"find_by":"agent_exists_find_by"},"outputs_map":{"bool":"agent_exists_find_by_result"}},"transitions_before":[],"transitions_after":[{"variable":"agent_exists_13_result_bool","operator":"==","value":"True","step_id":"44"}]}'),
(14, 2, 4, 'Вернуть список команд', 0, '{"transitions_before":[{"variable":"prompt_user","operator":"==","value":"/girl_create","step_id":"16"},{"variable":"prompt_user","operator":"==","value":"/girl_remove","step_id":"111"}],"transitions_after":[],"prompt_user":"%agent_greeting%","continue_workflow":false}'),
(15, 2, 4, 'dating_girl_create_response', 17, '{"prompt_user":"Девушка %girl_title_saved% успешно создана.\\n\\nБыло создано %fact_collection_add_20_result_facts_qty% фактов, синхронизировано в Qdrant: %qdrant_fact_sync_102_result_synced_qty%.","transitions_before":[],"transitions_after":[]}'),
(16, 2, 4, 'Спросить имя девушки', 1, '{"prompt_user":"Напишите желаемое имя девушки или выберите из списка:\\n\\n[[Таня]] [[Руслана]] [[Лена]] [[Вера]] [[Катя]] [[Маша]] [[Анна]] [[Елена]] ","transitions_before":[],"transitions_after":[],"continue_workflow":true}'),
(18, 2, 3, 'fact_collection_output_format', 11, '{"tool_invoke":{"tool_name":"fact_collection_output_format","inputs_map":{"collection_name":"fact_collection_girl_name"},"outputs_map":{"str":"fact_collection_output_format_response"}},"transitions_before":[],"transitions_after":[]}'),
(19, 2, 2, 'LLM -> JSON', 12, '{"transitions_before":[],"transitions_after":[],"llm_to_json_variable":[{"variable":"facts","text":"список фактов"}],"prompt_user":"Ниже приведена краткая биография девушки %girl_title_saved%, написанная пользователем. Составь на её основе структурированный список фактов.\\n\\n=== Биография ===\\n%prompt_user%\\n\\nПравила:\\n1. Главный источник — биография: каждое её утверждение преврати в отдельный короткий факт (один факт — одно утверждение).\\n2. Факты не должны противоречить биографии и друг другу.\\n3. Если каких-то тем в биографии нет, аккуратно дополни правдоподобными деталями в согласии с текстом. Темы: подростковый возраст, учеба, отношения с родителями, любимые занятия и увлечения, любовные отношения, путешествия, работа.\\n4. Всего фактов должно быть 24-32.\\n\\n=== Important information about final response ===\\nPlease return your response in JSON format. The JSON response must contain follow keys: \\n- \\"facts\\": список фактов\\n\\ndocument_id всегда \'%text_to_lower_37_result_str%\'\\n\\nExample of JSON response:\\n{\\n  \\"facts\\": %fact_collection_output_format_18_result_str%\\n}"}'),
(20, 2, 3, 'fact_collection_add', 15, '{"tool_invoke":{"tool_name":"fact_collection_add","inputs_map":{"collection_name":"fact_collection_girl_name","data":"facts","document_title":"girl_title_saved","user_id":"user_id"},"outputs_map":{"facts_qty":"facts_qty"}},"transitions_before":[],"transitions_after":[]}'),
(21, 2, 5, 'Переменные', 7, '{"transitions_before":[],"transitions_after":[],"variable_conversion":[{"variable":"agent_title","text":"%girl_title_saved%"},{"variable":"workflow_variable","text":"{\\"girl_id\\":\\"%text_to_lower_37_result_str%\\"}"},{"variable":"girl_description","text":"Описание девушки %girl_title_saved%"},{"variable":"girl_greeting","text":"Привет, я %girl_title_saved%, буду рада пообщаться с тобой"}]}'),
(22, 2, 3, 'text_translit_cyr_to_lat', 2, '{"tool_invoke":{"tool_name":"text_translit_cyr_to_lat","inputs_map":{"text":"prompt_user"},"outputs_map":{"str":"agent_name"}},"transitions_before":[],"transitions_after":[]}'),
(23, 2, 3, 'agent_create_or_update', 9, '{"tool_invoke":{"tool_name":"agent_create_or_update","inputs_map":{"name":"text_to_lower_37_result_str","title":"girl_title_saved","node_id":"node_id","workflow_id":"agent_workflow_id_28_result_int","workflow_variable":"workflow_variable","prompt_system":"girl_prompt_system","description":"girl_description","greeting":"girl_greeting","user_id":"user_id"},"outputs_map":{}},"transitions_before":[],"transitions_after":[]}'),
(24, 5, 2, 'Генерация ответа', 10, '{"llm_to_json_variable": [{"variable": "girl_response", "text": "ответ девушки собеседнику (пустая строка, если отвечать не нужно)"}], "prompt_user": "=== Текущее время ===\\n%datetime_current_get_45_result_str%\\n\\n%if session_messages_29_result_str%\\n=== История переписки (детально, время сообщений в квадратных скобках) ===\\n%session_messages_29_result_str%\\n%endif%\\n\\n%if session_messages_result_processed%\\n=== Краткая выдержка истории переписки ===\\n%session_messages_result_processed%\\n%endif%\\n\\n%if qdrant_fact_search_25_result_str%\\n=== Информация о %agent_name% в базе данных ===\\n%qdrant_fact_search_25_result_str%\\n%endif%\\n\\n%if qdrant_fact_search_38_result_str%\\n=== Информация о %companion_title% в базе данных ===\\n%qdrant_fact_search_38_result_str%\\n%endif%\\n\\n%if qdrant_fact_search_39_result_str%\\n=== Информация о предыдущих соглашениях ===\\n%qdrant_fact_search_39_result_str%\\n%endif%\\n\\n=== %companion_title% пишет ===\\n%prompt_user%\\n\\n=== Что нужно ===\\n1. Вернуть короткий ответ: одно-два предложения, до 20 слов, как в мессенджере.\\n2. Тон приземленный и современный: реальная жизнь — работа, быт, кафе, сериалы, спорт, поездки, планы. Без поэзии, высокопарных метафор и старомодной романтики (стихи, кружева, шелк, винтажные духи), если %companion_title% сам об этом не спросил.\\n3. Ответ должен соответствовать текущему времени суток и времени сообщений в истории (в квадратных скобках): не здоровайся и не описывай утренние дела вечером или ночью, и наоборот.\\n4. КРИТИЧЕСКОЕ ПРАВИЛО: Если сообщение %companion_title% — это неразборчивый набор букв, опечатка, случайные символы или у тебя нет четкого понимания, что ответить, ты ОБЯЗАНА вернуть абсолютно пустую строку (ни одного символа, пробела или знака препинания). Не пытайся отшучиваться или переспрашивать в таких случаях.\\n5. Отвечай строго на языке: %user_language%.\\n\\n=== Important information about final response ===\\nPlease return your response in JSON format. The JSON response must contain follow keys: \\n- \\"girl_response\\": твой ответ собеседнику; если по правилам выше отвечать не нужно - строго пустая строка\\n\\nExample of JSON response:\\n{\\n  \\"girl_response\\": \\"привет, как прошел день?\\"\\n}\\n\\nExample of JSON response one more:\\n{\\n  \\"girl_response\\": \\"\\"\\n}", "transitions_before": [], "transitions_after": []}'),
